import { useMemo } from 'react';

import { type RowData, type ColumnDef } from './useTable/types.js';
import { applyColumnFormatters } from '../features/CellFormatter.js';
import { applyColumnTypes } from '../features/ColumnTypes.js';
import {
  type DataTableV2ColumnDef,
  type DataTableV2DisplayColumnDef,
  type DataTableV2GroupColumnDef,
} from '../public.api.js';

/**
 * @internal
 * TypeGuard helper to verify that a given external columnDef is a GroupColumnDef
 */
function isDataTableV2GroupColumnDef<TData extends RowData, TValue = unknown>(
  columnDef: unknown,
): columnDef is DataTableV2GroupColumnDef<TData, TValue> {
  return (
    columnDef !== null &&
    typeof columnDef === 'object' &&
    'columns' in columnDef &&
    Array.isArray((columnDef as { columns: Array<unknown> }).columns)
  );
}

/**
 * @internal
 * TypeGuard helper to verify that a given external columnDef is a DisplayColumnDef
 */
function isDataTableV2DisplayColumnDef<TData extends RowData, TValue = unknown>(
  columnDef: unknown,
): columnDef is DataTableV2DisplayColumnDef<TData, TValue> {
  return (
    columnDef !== null &&
    typeof columnDef === 'object' &&
    'accessor' in columnDef
  );
}

/**
 * @internal
 * Helper function to transform the public accessor key to the correct
 * member config for the tanstack/react-table ColumnDef.
 */
function splitAccessor<TData extends RowData, TValue = unknown>(
  column: DataTableV2DisplayColumnDef<TData, TValue>,
): {
  accessorKey?: string;
  accessorFn?: (row: TData) => TValue;
} {
  if (typeof column.accessor === 'string') {
    // TODO: Add back the logic for nested accessors that contain a `.` character here.
    return {
      accessorKey: column.accessor,
    };
  }

  if (typeof column.accessor === 'function') {
    return {
      accessorFn: column.accessor,
    };
  }
  return {};
}

/**
 * @internal
 * Helper function to convert from the public `DataTableV2DisplayColumnDef` to the internally used
 * ColumnDef.
 */
function createDisplayColumnDef<TData extends RowData, TValue = unknown>(
  columnDef: DataTableV2DisplayColumnDef<TData, TValue>,
): ColumnDef<TData, TValue> {
  const composedDef: ColumnDef<TData, TValue> = {
    id: columnDef.id,
    header: columnDef.header,
    width: columnDef.width,
    alignment: columnDef.alignment,
    meta: {
      config: columnDef.config,
      hasFormatter: columnDef.formatter ? true : false,
    },
    ...splitAccessor(columnDef),
  };

  if (columnDef.columnType) {
    composedDef.columnType = columnDef.columnType;
  }

  if (columnDef.cell) {
    composedDef.cell = columnDef.cell;
    return composedDef;
  }

  return {
    ...composedDef,
    ...applyColumnTypes(columnDef),
    ...applyColumnFormatters(columnDef),
  };
}

/** Helper hook that will calculate which columns are enabled within the DataTable */
export function useColumns<TData>(
  propColumns: DataTableV2ColumnDef<TData>[],
  features: { selectableRows?: boolean },
) {
  return useMemo(() => {
    const createdColumns: ColumnDef<TData>[] = [];
    const propColumnMap = new Map<string, DataTableV2ColumnDef<TData>>();

    // Iterate through the columns and create the definitions required
    for (const firstLevelColumn of propColumns) {
      propColumnMap.set(firstLevelColumn.id, firstLevelColumn);
      if (isDataTableV2GroupColumnDef(firstLevelColumn)) {
        const groupColumn: ColumnDef<TData> = {
          id: firstLevelColumn.id,
          header: firstLevelColumn.header,
          cell: firstLevelColumn.cell,
          width: firstLevelColumn.width,
          columns: firstLevelColumn.columns?.map((col) =>
            createDisplayColumnDef<TData>(
              // Casted here because DataTableV2DisplayColumnDef failed to capture the TData type and fall back to unknown
              col as DataTableV2DisplayColumnDef<TData, unknown>,
            ),
          ),
          alignment: firstLevelColumn.alignment,
        };
        createdColumns.push(groupColumn);

        for (const secondLevelColumn of firstLevelColumn.columns ?? []) {
          propColumnMap.set(secondLevelColumn.id, secondLevelColumn);
        }
      } else if (isDataTableV2DisplayColumnDef(firstLevelColumn)) {
        createdColumns.push(createDisplayColumnDef<TData>(firstLevelColumn));
      }
    }

    return [createdColumns, propColumnMap] as const;
  }, [propColumns]);
}
